def seed_topics_and_migrate_problems(apps, schema_editor):
    Topic = apps.get_model("core", "CodingTopic")
    Problem = apps.get_model("core", "CodingProblem")
    topics = {}
    for name in CODING_TOPICS:
        topic, _ = Topic.objects.get_or_create(
            slug=django.utils.text.slugify(name),
            defaults={"name": name, "is_active": True},
        )
        topics[name] = topic

    legacy_mapping = {
        "Programming": "Basic Programming",
        "Data Structures": "Arrays",
        "Algorithms": "Searching",
        "DBMS": "Basic Programming",
    }
    used_slugs = set()
    for problem in Problem.objects.all().order_by("pk"):
        topic_name = problem.category if problem.category in topics else legacy_mapping.get(
            problem.category,
            "Basic Programming",
        )
        problem.topic = topics[topic_name]
        if not problem.problem_statement:
            problem.problem_statement = problem.description
        base_slug = django.utils.text.slugify(problem.title) or f"problem-{problem.pk}"
        slug = base_slug
        suffix = 2
        while slug in used_slugs:
            slug = f"{base_slug}-{suffix}"
            suffix += 1
        used_slugs.add(slug)
        problem.slug = slug
        problem.category = topic_name
        problem.save(update_fields=["topic", "problem_statement", "slug", "category"])


